#[path = "../../services/dashboards/rust/src/raster.rs"]
mod raster;
use raster::{ColorMode, gray_pixel};

#[test]
fn preserved_pngjs_alpha_luminance_and_threshold_vectors() {
    // Captured from the original convertPng, not generated by the Rust function.
    let pixels = [
        [255, 0, 0, 255],
        [0, 255, 0, 255],
        [0, 0, 255, 255],
        [0, 0, 0, 0],
        [0, 0, 0, 128],
        [255, 255, 255, 128],
        [127, 127, 127, 255],
        [128, 128, 128, 255],
    ];
    assert_eq!(
        pixels.map(|p| gray_pixel(p, ColorMode::Grayscale)),
        [54, 182, 18, 255, 127, 255, 127, 128]
    );
    assert_eq!(
        pixels.map(|p| gray_pixel(p, ColorMode::Monochrome)),
        [0, 255, 0, 255, 0, 255, 0, 255]
    );
}

#[test]
fn fully_transparent_pixels_are_white_and_monochrome_has_only_two_values() {
    for alpha in 0..=255 {
        for value in 0..=255 {
            let gray = gray_pixel([value, 255 - value, value / 2, alpha], ColorMode::Grayscale);
            let mono = gray_pixel(
                [value, 255 - value, value / 2, alpha],
                ColorMode::Monochrome,
            );
            if alpha == 0 {
                assert_eq!(gray, 255);
            }
            assert_eq!(mono, if gray >= 128 { 255 } else { 0 });
        }
    }
    assert_eq!(gray_pixel([255; 4], ColorMode::Color), 255);
}
